import {renderCompanions} from './companions-ui.mjs?v=0.5';
import {renderEquipment,characterSummary} from './equipment-ui.mjs?v=0.5';
import {itemIcon} from './avatar.mjs?v=0.5';
import {GRADES,MATERIALS,SLOTS,RECIPES,PETS,amount,canMaterials,gearRecipe,itemStats,enhancementRecipe,materialPlan} from './economy.mjs?v=0.5';
import {REGIONS,regionUnlocked,regionById} from './regions.mjs?v=0.5';
const ui={grade:0,slot:'mainhand',material:'ore',selected:null,filter:'all',quantity:1};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tag=g=>`<span class="grade-tag rarity-${g}">${GRADES[g].color} · ${GRADES[g].name}</span>`;
const statsText=it=>Object.entries(itemStats(it)).filter(([,v])=>v).map(([k,v])=>`${{hp:'HP',mp:'Linh lực',atk:'Công',def:'Thủ'}[k]} +${v}`).join(' · ');
const itemName=i=>`${SLOTS[i.slot].name} · Bậc ${['','I','II','III','IV'][i.tier]} +${i.enhance}`;
const nav={loadout:'Trang bị',forge:'Lò rèn',materials:'Nguyên liệu',pets:'Pet',mounts:'Thú cưỡi',skills:'Kỹ năng',atlas:'Thế giới',codex:'Bách khoa',equipment:'Tu luyện',inventory:'Túi đồ',saves:'Xuất / nhập lưu',journal:'Nhiệm vụ'};
export function renderProgression(which,c){if(renderCompanions(which,c))return true;if(renderEquipment(which,c,ui))return true;if(!['loadout','forge','materials','pets','atlas','codex'].includes(which))return false;const {game,openModal,closeModal,showPanel,save,hud}=c,s=game.s,$=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)];
const rerender=()=>{save();showPanel(which);hud();};
const gradeTabs=`<div class="grade-tabs">${GRADES.map((g,i)=>`<button class="rarity-${i} ${i===ui.grade?'selected':''}" data-grade="${i}">${g.color}<small>${g.name}</small></button>`).join('')}</div>`;
const recipeRows=(r,g)=>`<div class="recipe-list">${Object.entries(r).map(([k,n])=>`<div class="rarity-${g}"><span>${MATERIALS[k].icon} ${MATERIALS[k].name}</span><b class="${amount(s,k,g)>=n?'enough':'missing'}">${amount(s,k,g)} / ${n}</b><small>Khóa ${s.materials[k][g].bound} · Giao dịch ${s.materials[k][g].trade}</small></div>`).join('')}</div>`;
let body='',subtitle='';
if(which==='materials'){
 subtitle='Ghép 10 → 1 màu kế tiếp, thành công 100%. Mỗi sản phẩm có 20% cơ hội giao dịch. Nguyên liệu thu thập mặc định khóa.';
 body=gradeTabs+`<label class="select-line">Ưu tiên tiêu hao <select id="materialPreference"><option value="bound-first" ${s.materialPreference==='bound-first'?'selected':''}>Dùng khóa trước</option><option value="trade-first" ${s.materialPreference==='trade-first'?'selected':''}>Dùng giao dịch trước</option></select></label><div class="material-grid">${Object.entries(MATERIALS).map(([k,m])=>{const a=s.materials[k][ui.grade];return `<article class="material-card rarity-${ui.grade}"><span class="item-symbol">${itemIcon(k,ui.grade)}</span><h3>${m.name}</h3><strong>${a.bound+a.trade}</strong><small>Khóa ${a.bound} · Giao dịch ${a.trade}</small><p>${m.source}</p><button data-fuse="${k}" ${ui.grade===4||a.bound+a.trade<10?'disabled':''}>${ui.grade===4?'Phẩm chất cao nhất':'Ghép 10 → 1 '+GRADES[ui.grade+1].color}</button>${ui.grade<4?`<button data-fuse-ten="${k}" ${a.bound+a.trade<100?'disabled':''}>Ghép 100 → 10</button>`:''}</article>`;}).join('')}</div><h3>Luyện đá cường hóa ${tag(ui.grade)}</h3>${recipeRows({ore:2,energy:1},ui.grade)}<button id="refineStone" ${!canMaterials(s,{ore:2,energy:1},ui.grade)?'disabled':''}>Luyện 1 đá · Thành công 100% · Giao dịch 20%</button><h3>Tính nguyên liệu cần farm</h3><div class="form-row"><select id="planMaterial">${Object.entries(MATERIALS).map(([k,m])=>`<option value="${k}" ${k===ui.material?'selected':''}>${m.name}</option>`).join('')}</select><label>Số lượng đích <input id="planQuantity" type="number" min="1" max="1000" value="${ui.quantity}"></label><button id="planApply">Tính</button></div><table class="craft-table"><thead><tr><th>Phẩm chất</th><th>Cần</th><th>Đang có</th><th>Còn thiếu</th></tr></thead><tbody>${materialPlan(s,ui.material,ui.grade,ui.quantity).map(row=>`<tr><td>${tag(row.grade)}</td><td>${row.need.toLocaleString()}</td><td>${row.owned.toLocaleString()}</td><td>${row.missing.toLocaleString()}</td></tr>`).join('')}</tbody></table><p class="subtext">Ước tính quy đổi 10:1 từ các màu thấp; không tự động tiêu hao. Bạn cũng có thể thu thập trực tiếp mỏ đúng màu tại khu vực tương ứng.</p>`;
}
if(which==='loadout'){
 subtitle='Nhân vật mặc đúng trang bị đang chọn. Kéo để xoay, lăn chuột để phóng to; chọn ô đồ để chế tạo hoặc thay món.';
 body=characterSummary(s)+`<div class="character-showcase"><section class="avatar-stage"><div class="avatar-title"><span class="eyebrow">LỮ KHÁCH · CẤP ${s.level}</span><h3>${esc(s.name)}</h3></div><canvas id="avatarCanvas" aria-label="Nhân vật 3D với trang bị đang mặc, kéo để xoay"></canvas><div class="avatar-controls"><button id="avatarLeft" aria-label="Xoay nhân vật trái">↶</button><span>Kéo để xoay 360°</span><button id="avatarRight" aria-label="Xoay nhân vật phải">↷</button></div></section><div class="loadout-grid">${Object.entries(SLOTS).map(([slot,v])=>{const it=s.items.find(i=>i.id===s.equipped[slot]);return `<article class="gear-preview ${it?'rarity-'+it.grade:'empty-slot'}"><span class="item-symbol">${itemIcon(slot,it?.grade??0)}</span><h3>${v.name}</h3>${it?`${tag(it.grade)}<p>Bậc ${it.tier} +${it.enhance} · ${it.tradable?'Giao dịch':'Khóa'}</p><small>${statsText(it)}</small><button data-remove="${slot}">Tháo</button>`:'<p>Ô trống</p>'}<button data-make="${slot}">${it?'Rèn / thay trang bị':'Chế tạo'}</button></article>`;}).join('')}</div></div><p class="subtext">Các điểm tu luyện cũ được giữ riêng; trang bị mới cộng thêm chỉ số. Vật phẩm đang mặc hoặc bảo vệ không thể dùng làm phôi ghép.</p>`;
}
if(which==='atlas'){
 const near=Math.hypot(s.x-game.getRegion().portal.x,s.z-game.getRegion().portal.z)<=6;
 subtitle='Mỗi map có quái, boss, tài nguyên và tiến trình riêng. Đến cổng dịch chuyển ở tiền trạm để chuyển map.';
 body=`<div class="toolbar"><button id="toPortal">⌖ Đến cổng dịch chuyển</button><button data-nav="map">Bản đồ thu nhỏ phóng lớn</button><span>${near?'Bạn đang ở cổng · Có thể chuyển map':'Cổng tại 37 · 120'}</span></div><div class="region-grid">${REGIONS.map((r,i)=>{const unlocked=regionUnlocked(s,i),done=i?s.regions[r.id].quest:s.quest;return `<article class="region-card biome-${r.biome} ${r.id===s.map?'current':''}"><div class="region-illustration">${['山','竹','❄','火','☁'][i]}</div><span class="eyebrow">${r.subtitle}</span><h3>${r.name}</h3><p>${r.description}</p>${tag(r.grade)}<p>Cấp gợi ý ${r.level} · Nhiệm vụ ${done}/${i?4:12}</p><small>${unlocked?'Đã mở':r.unlockText}</small><button data-travel="${r.id}" ${!unlocked||!near||r.id===s.map?'disabled':''}>${r.id===s.map?'Đang ở đây':unlocked?'Chuyển đến '+r.name:'Chưa mở khóa'}</button><details><summary>Nhiệm vụ khu vực</summary>${r.quests.length?r.quests.map((q,j)=>`<p>${j<done?'✓':j+1+'.'} ${q.title} — ${q.text}</p>`).join(''):'<p>12 nhiệm vụ chính tuyến: xem Nhật ký.</p>'}</details></article>`;}).join('')}</div>`;
}
if(which==='codex'){
 subtitle='Bách khoa Long Mạch · Các quy tắc đang hoạt động trong bản 0.5';
 body=`<div class="codex-grid"><article><h3>Phẩm chất</h3>${GRADES.map((g,i)=>`<p>${tag(i)}</p>`).join('')}<p>Áp dụng cho mọi nguyên liệu chế tạo, đá cường hóa và trang bị. Đồng là tiền tệ, bình thuốc là vật phẩm tiêu hao.</p></article><article><h3>Chuỗi chế tạo</h3><ol><li>Thu mỏ cùng màu → nguyên liệu khóa.</li><li>Ghép 10 cùng loại/màu → 1 màu kế, không mất khi thất bại vì tỷ lệ thành công là 100%.</li><li>Chế trang bị từ công thức cùng màu → bậc I +0.</li><li>Ghép 2 cùng loại/màu/bậc +0 → bậc II, III, IV.</li><li>Cường hóa bằng đá cùng màu đến +8.</li><li>Đồ IV +8 cùng vật liệu màu kế → đồ màu kế I +0, tiêu hao phôi.</li></ol></article><article><h3>Giao dịch 20%</h3><p>Mỗi sản phẩm khi ghép nguyên liệu, luyện đá, chế/ghép/thăng phẩm trang bị có một lần thử xác suất 20%. Các lần độc lập; không bảo đảm cứ 5 lần có 1 món giao dịch.</p><p>Cường hóa giữ nhãn cũ. Giao dịch hiện là thuộc tính vật phẩm trong kho; chợ người chơi cần giai đoạn online.</p></article><article><h3>Nhóm công thức</h3>${Object.entries(RECIPES).map(([k,r])=>`<p><b>${r.name}:</b> ${Object.entries(r.materials).map(([m,n])=>n+' '+MATERIALS[m].name).join(' + ')} cùng màu.</p>`).join('')}<p>Mỗi món còn cần 40 × (bậc màu + 1) đồng.</p></article><article><h3>Nguồn tài nguyên</h3><p>Khoáng → Thanh Thạch + Huyền thiết. Hái thuốc → Linh thảo + Linh bì. Hấp thu → Linh khí + Ngọc tinh + Thiên vũ. Săn quái → Linh phách. Boss còn thưởng Thiên vũ.</p><p>Vân Sơn: Trắng; Trúc Hải: Xanh lá; Băng Hồ: Xanh lam; Hỏa Sơn: Đỏ; Thiên Cung: Vàng. Mỏ hồi sau 13 giây.</p></article><article><h3>Điều khiển & hành trình</h3><p>M: bản đồ khu vực · N: thế giới · I: lò rèn · C: trang bị · B: túi đồ · P: pet · T: auto nhiệm vụ.</p><p>Auto dừng ở công thức cần bạn lựa chọn. Mở bản đồ để xem điều kiện mở map và đến cổng. Mỗi khu vực giữ tiến trình khi rời đi.</p><p>Chơi đơn, lưu trên thiết bị. Nhiều người có thể chơi riêng qua cùng đường dẫn.</p></article></div><details><summary>Nguồn tham khảo thiết kế & định hướng</summary><p><a href="https://forum.mir4global.com/board/dictionary" target="_blank" rel="noopener">Bách khoa MIR4</a> · <a href="https://forum.mir4global.com/post/34" target="_blank" rel="noopener">Forge</a> · <a href="https://mirkit.mir4collection.com/craft" target="_blank" rel="noopener">Mirkit Craft</a></p><p>Cốt truyện và công thức Long Mạch được thiết kế riêng theo yêu cầu của bạn. Hướng phát triển sau: tổ đội, bang hội, phụ bản, PvP và chợ có máy chủ.</p></details>`;
}
openModal(`<span class="eyebrow">LONG MẠCH · ${esc(game.getRegion().name)}</span><h2 class="modal-title">${nav[which]}</h2><div class="panel-tabs">${Object.entries(nav).map(([k,v])=>`<button data-nav="${k}" class="${which===k?'active':''}">${v}</button>`).join('')}</div><p class="subtext">${subtitle}</p>${body}`,which);
$$('[data-nav]').forEach(b=>b.onclick=()=>showPanel(b.dataset.nav));$$('[data-grade]').forEach(b=>b.onclick=()=>{ui.grade=+b.dataset.grade;showPanel(which);});
$('#materialPreference')?.addEventListener('change',e=>{s.materialPreference=e.target.value;save();});$$('[data-fuse]').forEach(b=>b.onclick=()=>{game.fuseMaterial(b.dataset.fuse,ui.grade);rerender();});$$('[data-fuse-ten]').forEach(b=>b.onclick=()=>{game.fuseMaterial(b.dataset.fuseTen,ui.grade,10);rerender();});$('#refineStone')?.addEventListener('click',()=>{game.refineStone(ui.grade);rerender();});$('#planApply')?.addEventListener('click',()=>{ui.material=$('#planMaterial').value;ui.quantity=Math.min(1000,Math.max(1,Math.floor(+$('#planQuantity').value)||1));showPanel(which);});
$$('[data-remove]').forEach(b=>b.onclick=()=>{game.unequip(b.dataset.remove);rerender();});$$('[data-make]').forEach(b=>b.onclick=()=>{ui.slot=b.dataset.make;ui.filter=b.dataset.make;ui.selected=s.equipped[ui.slot]||null;showPanel(ui.selected?'inventory':'forge');});$$('[data-pet-up]').forEach(b=>b.onclick=()=>{game.upgradePet(b.dataset.petUp);rerender();});$$('[data-pet]').forEach(b=>b.onclick=()=>{game.choosePet(b.dataset.pet);rerender();});$('#toPortal')?.addEventListener('click',()=>{closeModal();game.goto(game.getRegion().portal.x,game.getRegion().portal.z);});$$('[data-travel]').forEach(b=>b.onclick=()=>{closeModal();game.travel(b.dataset.travel);save();hud();});return true;
}
